$toolName = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("8J+TgV9NMTFfVE9PTF9QQw=="))
$engName  = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("8J+TgV9FbmdpbmVzX0FuZF9TY3JpcHRz"))

function Write-Utf8NoBom([string]$Path, [byte[]]$Bytes) {
    $dir = Split-Path $Path -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    [System.IO.File]::WriteAllBytes($Path, $Bytes)
}

# ---------------------------------------------------------------- inventory
Log '[A] Inventory'
$desks = @()
foreach ($p in (Get-ChildItem 'C:\Users' -Directory -ErrorAction SilentlyContinue)) {
    $d = Join-Path $p.FullName 'Desktop'
    if (Test-Path $d) { $desks += $d }
}
$desks += 'C:\Users\Public\Desktop'
$desks = $desks | Select-Object -Unique
foreach ($d in $desks) { Log ("    desktop: " + $d) }

# ------------------------------------------------- 1. mojibake cleanup
Log '[B] Removing mojibake (?) items'
$removed = 0
foreach ($d in $desks) {
    Get-ChildItem -LiteralPath $d -Force -Recurse -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -match '^\?{1,4}[_\\.]' } |
        ForEach-Object {
            Log ("    removing: " + $_.FullName)
            try { Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction Stop; $removed++ }
            catch { Log ("    locked: " + $_.Exception.Message) }
        }
}
Log ("    removed " + $removed + " items")

# ------------------------------------------------- 2. locate toolkit
Log '[C] Locating toolkit folders'
$toolDirs = @()
foreach ($d in $desks) {
    $toolDirs += (Get-ChildItem -LiteralPath $d -Directory -Force -ErrorAction SilentlyContinue |
                  Where-Object { $_.Name -like '*M11_TOOL_PC*' } | Select-Object -ExpandProperty FullName)
}
if ($toolDirs.Count -eq 0) {
    foreach ($d in $desks) {
        if ($d -like '*M11 Dev-Tool*') {
            $nd = Join-Path $d $toolName
            New-Item -ItemType Directory -Path $nd -Force | Out-Null
            $toolDirs += $nd
        }
    }
}
$toolDirs = $toolDirs | Select-Object -Unique
foreach ($t in $toolDirs) { Log ("    toolkit: " + $t) }

# ------------------------------------- 2b. purge OLD M11 builds (stale copies)
Log '[C2] Purging old M11 builds inside the toolkit'
$managedNames = @(
    'M11_MASTER_RUNNER.bat', 'M11_MASTER_CONTROL_CENTER.bat', 'MASTER_RUNNER.bat',
    'M11_UNIVERSAL_STORE.bat', 'DOWNLOAD_GTA_V_AND_HEAVY_GAMES.bat',
    'M11_GAMES_HUB.bat', 'M11_MASTER_RUNNER.bat', 'MASTER_CONTROL_CENTER.bat',
    'M11_SELF_TEST.bat', '_M11_SELF_TEST.bat'
)
$purgedOld = 0
foreach ($t in $toolDirs) {
    Get-ChildItem -LiteralPath $t -Recurse -File -Force -ErrorAction SilentlyContinue | ForEach-Object {
        $base = $_.Name
        foreach ($m in $managedNames) {
            if ($base -like ('*' + $m)) {
                # our fresh build is written again in the next step, so removing is safe
                Log ('    removing old build: ' + $_.FullName.Replace($t, '<toolkit>'))
                Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue
                $purgedOld++
                break
            }
        }
    }
    # drop now-empty engine folders left behind (wrong-name variants)
    Get-ChildItem -LiteralPath $t -Directory -Recurse -Force -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -like '*_Engines_And_Scripts*' -and $_.Name -ne $engName } |
        ForEach-Object {
            if (-not (Get-ChildItem -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue)) {
                Log ('    removing empty variant folder: ' + $_.Name)
                Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
}
Log ('    purged ' + $purgedOld + ' old toolkit files')

# ------------------------------------------------- 3. deploy fixed files
Log '[D] Deploying corrected files (UTF-8, no BOM)'
foreach ($t in $toolDirs) {
    $engDir = Join-Path $t $engName
    if (-not (Test-Path $engDir)) {
        $found = Get-ChildItem -LiteralPath $t -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -like '*Engines_And_Scripts*' } | Select-Object -First 1
        if ($found) { $engDir = $found.FullName } else { New-Item -ItemType Directory -Path $engDir -Force | Out-Null }
    }
    foreach ($item in $payload) {
        $bytes = [Convert]::FromBase64String($item.b64)
        if ($item.sub -eq 'eng') {
            Write-Utf8NoBom (Join-Path $engDir $item.name) $bytes
        } else {
            Write-Utf8NoBom (Join-Path $t $item.name) $bytes
        }
        Log ("    + " + $item.name)
    }
}
# desktop copies of the launchers (engine files stay inside their folder)
foreach ($d in $desks) {
    foreach ($item in $payload) {
        if ($item.sub -ne 'eng') {
            Write-Utf8NoBom (Join-Path $d $item.name) ([Convert]::FromBase64String($item.b64))
        }
    }
}
# the engines folder must contain numbered engines only - drop stale launcher copies
$engPurged = 0
foreach ($t in $toolDirs) {
    foreach ($e in @($engName) + @((Get-ChildItem -LiteralPath $t -Directory -Force -ErrorAction SilentlyContinue |
                                   Where-Object { $_.Name -like '*_Engines_And_Scripts*' }).Name)) {
        $engDir2 = Join-Path $t $e
        if (-not (Test-Path $engDir2)) { continue }
        Get-ChildItem -LiteralPath $engDir2 -File -Force -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -notmatch '^[0-9]' } | ForEach-Object {
                Log ('    engines: removing stale copy ' + $_.Name)
                Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue
                $script:engPurged++
            }
    }
}
Log ('    engines folder cleaned (' + $engPurged + ' stale copies removed)')
Log '    desktop copies written'

# --------------------------------------------- 3b. purge stale mojibake files
Log '[D2] Purging files whose CONTENT is still mojibake'
$purged = 0
$roots = @($desks) + @($toolDirs)
foreach ($r in ($roots | Select-Object -Unique)) {
    if (-not (Test-Path $r)) { continue }
    Get-ChildItem -LiteralPath $r -Recurse -File -Force -ErrorAction SilentlyContinue | ForEach-Object {
        if ($_.Length -gt 300000) { return }
        if ($_.Extension -notmatch '\.(bat|cmd|ps1|json|txt)$') { return }
        try {
            $t = [System.IO.File]::ReadAllText($_.FullName)
            if ($t -match '\?\?\?\?\?') {
                Log ('    purging: ' + $_.FullName)
                Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue
                $purged++
            }
        } catch { }
    }
}
Log ('    purged ' + $purged + ' mojibake files')

# ------------------------------------------------- 4. auto-logon
Log '[E] Auto-logon'
try {
    $wl = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'
    Set-ItemProperty -Path $wl -Name 'AutoAdminLogon'    -Value '1'           -Type String -Force -ErrorAction Stop
    Set-ItemProperty -Path $wl -Name 'DefaultUserName'   -Value 'M11 Dev-Tool' -Type String -Force -ErrorAction Stop
    Set-ItemProperty -Path $wl -Name 'DefaultPassword'   -Value 'M11Pass#2026' -Type String -Force -ErrorAction Stop
    Set-ItemProperty -Path $wl -Name 'DefaultDomainName' -Value $env:COMPUTERNAME -Type String -Force -ErrorAction Stop
    Remove-ItemProperty -Path $wl -Name 'AutoLogonCount' -ErrorAction SilentlyContinue
    Set-ItemProperty -Path $wl -Name 'ForceAutoLogon' -Value '1' -Type String -Force -ErrorAction SilentlyContinue
    Log ('    AutoAdminLogon = ' + (Get-ItemProperty $wl).AutoAdminLogon)
} catch { Log ('    [FAIL] ' + $_.Exception.Message) }

# ------------------------------------------------- 5. RDP session policy
Log '[F] RDP session policy'
try {
    $ts = 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server'
    Set-ItemProperty -Path $ts -Name 'fSingleSessionPerUser' -Value 1 -Type DWord -Force -ErrorAction Stop
    Set-ItemProperty -Path $ts -Name 'fDenyTSConnections'    -Value 0 -Type DWord -Force -ErrorAction Stop
    $rdp = Join-Path $ts 'WinStations\RDP-Tcp'
    Set-ItemProperty -Path $rdp -Name 'MaxDisconnectionTime' -Value 900000 -Type DWord -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path $rdp -Name 'MaxIdleTime'          -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
    Log '    single-session + disconnect timeout configured'
    Restart-Service TermService -Force -ErrorAction SilentlyContinue
    Log '    TermService restarted'
} catch { Log ('    [FAIL] ' + $_.Exception.Message) }

# ------------------------------------------------- 6. profiles
Log '[G] Profile reconciliation'
$loaded = @()
try { $loaded = @(Get-CimInstance Win32_UserProfile -ErrorAction SilentlyContinue | Where-Object { $_.Loaded } | Select-Object -ExpandProperty LocalPath) } catch { }
foreach ($s in (Get-ChildItem 'C:\Users' -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'M11 Dev-Tool.*' })) {
    if ($loaded -contains $s.FullName) { Log ('    skip (loaded): ' + $s.Name); continue }
    foreach ($sub in @('Desktop','Documents','Downloads')) {
        $from = Join-Path $s.FullName $sub
        $to   = Join-Path 'C:\Users\M11 Dev-Tool' $sub
        if (Test-Path $from) {
            if (-not (Test-Path $to)) { New-Item -ItemType Directory -Path $to -Force | Out-Null }
            robocopy $from $to /E /R:0 /W:0 /NFL /NDL /NJH /NJS /NP | Out-Null
        }
    }
    Log ('    removed stale profile dir: ' + $s.Name)
    cmd.exe /c "rd /s /q `"$($s.FullName)`"" 2>$null
}

# ------------------------------------------------- 7. verify
Log '[H] VERIFY'
foreach ($d in $desks) {
    if (-not (Test-Path $d)) { continue }
    $items = @(Get-ChildItem -LiteralPath $d -Force -ErrorAction SilentlyContinue)
    Log ('    ' + $d + ' -> ' + $items.Count + ' items')
    foreach ($i in $items) { Log ('        - ' + $i.Name) }
}
$bad = 0
foreach ($d in $desks) {
    Get-ChildItem -LiteralPath $d -Recurse -Force -ErrorAction SilentlyContinue | ForEach-Object {
        if ($_.Name -match '^\?+') { $bad++; Log ('    MOJIBAKE NAME: ' + $_.FullName) }
        elseif (-not $_.PSIsContainer -and $_.Length -lt 300000 -and $_.Extension -match '\.(bat|cmd|ps1|json|txt)$') {
            $t = [System.IO.File]::ReadAllText($_.FullName)
            if ($t -match '\?\?\?\?\?') { $bad++; Log ('    MOJIBAKE CONTENT: ' + $_.FullName) }
        }
    }
}
Log ('    mojibake items remaining: ' + $bad)
Log '[I] Toolkit listing'
foreach ($t in $toolDirs) {
    Get-ChildItem -LiteralPath $t -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object {
        Log ('    ' + $_.FullName.Replace($t, '<toolkit>') + '  [' + $_.Length + ' bytes]')
    }
}

# ------------------------------------------------- 8. legacy cleanup
Log '[J] Legacy cleanup (files left by the earlier failed attempts)'
$legacyFiles = @(
    'C:\\M11Data\\s02A.ps1','C:\\M11Data\\s02E.ps1','C:\\M11Data\\s02F.ps1','C:\\M11Data\\s02G.ps1',
    'C:\\M11Data\\s02H.ps1','C:\\M11Data\\s02I.ps1','C:\\M11Data\\s05B.ps1',
    'C:\\M11Data\\bom_s02E.ps1','C:\\M11Data\\bom_s02F.ps1','C:\\M11Data\\bom_s02G.ps1',
    'C:\\M11Data\\bom_s02H.ps1','C:\\M11Data\\bom_s02I.ps1','C:\\M11Data\\bom_m11_repair_master.ps1',
    'C:\\M11Data\\bom_m11_repair_run.ps1','C:\\M11Data\\m11_repair_master.ps1','C:\\M11Data\\m11_repair_run.ps1',
    'C:\\M11Data\\m11_repair_log.txt','C:\\M11Data\\m11_repair_log2.txt','C:\\M11Data\\remote_out.txt',
    'C:\\M11Data\\m11_task_inner.bat','C:\\M11Data\\m11_task_outer.bat','C:\\M11Data\\_m11_task_run.bat',
    'C:\\M11Data\\_out.txt','C:\\M11Data\\_done.txt','C:\\M11Data\\_exitcode.txt','C:\\M11Data\\watchdog_state.zip'
)
$gone = 0
foreach ($lf in $legacyFiles) {
    if (Test-Path $lf) { Remove-Item -LiteralPath $lf -Force -ErrorAction SilentlyContinue; $gone++ }
}
Log ("    removed " + $gone + " legacy debug files")

# duplicate control-center variant produced during the first fix pass
foreach ($d in $desks) {
    Get-ChildItem -LiteralPath $d -Recurse -Force -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -like ([char]0x2699 + '_*') } |
        ForEach-Object { Log ('    removing duplicate variant: ' + $_.Name); Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction SilentlyContinue }
}
# the broken 2.4 KB self test written by v1.11
foreach ($t in $toolDirs) {
    Get-ChildItem -LiteralPath $t -Recurse -Force -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -eq 'M11_SELF_TEST.bat' } |
        ForEach-Object { Log ('    removing broken self test: ' + $_.FullName); Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue }
}
Log '    legacy cleanup done'

# ------------------------------------------------- 9. persistence daemon self-heal
Log '[K] Persistence daemon check'
$dmn = 'C:\M11Data\m11_persistent_daemon.ps1'
if (Test-Path $dmn) {
    $txt = [System.IO.File]::ReadAllText($dmn)
    $patched = $false

    if ($txt -match 'Get-FileHash') {
        # Get-FileHash is not resolvable in the stripped runner shell -> .NET instead
        $old = '$sha256 = (Get-FileHash -Algorithm SHA256 -Path $zipPath).Hash'
        $new = "try { `$sha256 = [System.BitConverter]::ToString([System.Security.Cryptography.SHA256]::Create().ComputeHash([System.IO.File]::ReadAllBytes(`$zipPath))).Replace('-','') } catch { `$sha256 = (Get-Item `$zipPath).Length.ToString() }"
        $txt = $txt.Replace($old, $new)
        $patched = $true
        Log '    daemon hash function upgraded to .NET SHA256'
    }

    if ($txt -notmatch 'sync_now\.trigger') {
        Log '    daemon is an old build (no on-demand trigger) - fetching the fixed daemon'
        try {
            curl.exe -fsSL 'https://raw.githubusercontent.com/Free-RDP2/m11-tool-pc/main/m11_persistent_daemon.ps1' -o 'C:\M11Data\_new_daemon.ps1'
            if ((Test-Path 'C:\M11Data\_new_daemon.ps1') -and ((Get-Item 'C:\M11Data\_new_daemon.ps1').Length -gt 500)) {
                $liveToken = ''
                if ($txt -match '\$token = "([^"]+)"') { $liveToken = $matches[1] }
                $liveRepo = 'Free-RDP2/m11-tool-pc'
                if ($txt -match '\$repo = "([^"]+)"') { $liveRepo = $matches[1] }
                $newText = [System.IO.File]::ReadAllText('C:\M11Data\_new_daemon.ps1')
                $newText = $newText.Replace('REPLACE_PAT', $liveToken).Replace('REPLACE_GHT', $liveToken).Replace('REPLACE_REPO', $liveRepo)
                [System.IO.File]::WriteAllText($dmn, $newText, (New-Object System.Text.UTF8Encoding($false)))
                $patched = $true
                Log '    fixed daemon installed (existing token preserved)'
            }
        } catch { Log ('    daemon download failed: ' + $_.Exception.Message) }
    } elseif ($patched) {
        [System.IO.File]::WriteAllText($dmn, $txt, (New-Object System.Text.UTF8Encoding($false)))
    }

    if ($patched) {
        Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" -ErrorAction SilentlyContinue |
            Where-Object { $_.CommandLine -like '*m11_persistent_daemon*' } |
            ForEach-Object { Log ('    stopping daemon pid ' + $_.ProcessId); Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }
        Start-Sleep -Seconds 2
        Start-Process -FilePath 'powershell.exe' -ArgumentList '-NoProfile -ExecutionPolicy Bypass -File C:\M11Data\m11_persistent_daemon.ps1 -Daemon' -WindowStyle Hidden
        Start-Sleep -Seconds 30
        if (Test-Path 'C:\M11Data\m11_sync.log') {
            Get-Content 'C:\M11Data\m11_sync.log' -Tail 5 | ForEach-Object { Log ('    ' + $_) }
        }
        Log '    daemon restarted with the fixed build'
    } else {
        Log '    daemon already up to date'
    }
} else {
    Log '    no daemon installed yet (it is deployed automatically on the next session start)'
}
Log '===================== M11 v1.13 REPAIR END ====================='
